from pybricks.hubs import PrimeHub
from pybricks.parameters import Axis, Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up all devices.
prime_hub = PrimeHub(top_side=Axis.Z, front_side=Axis.X)
MT_1 = Motor(Port.F, Direction.COUNTERCLOCKWISE)
motor_2 = Motor(Port.D, Direction.CLOCKWISE)
Att_MTR = Motor(Port.A, Direction.CLOCKWISE)
Att_MTR_2 = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(MT_1, motor_2, 86, 132)


# The main program starts here.
drive_base.use_gyro(True)
drive_base.straight(650)
Att_MTR_2.run_angle(650, 193)
drive_base.turn(-90)
drive_base.turn(90)
MT_1.stop()
drive_base.turn(-110)
wait(500)
drive_base.straight(100)
Att_MTR_2.run_angle(650, 200)
drive_base.straight(-115)
drive_base.turn(75)
drive_base.straight(60)
Att_MTR_2.run_angle(650, -290)
drive_base.straight(140)
Att_MTR_2.run_angle(650, 350)
drive_base.straight(-190)
drive_base.turn(100)
drive_base.straight(290)
drive_base.turn(75)
drive_base.straight(100)
Att_MTR_2.run_angle(650, -290)
